// ---------------- HSE awareness: zones, nearby equipment, inspect ----------------
const ZN=[[87.5,10,16,'RED','Flare pit exclusion zone: no ignition sources, no entry'],[-8.5,16,5,'RED','Crane lifting zone: keep clear of the load and boom'],[-35,48.5,6,'GREEN','Muster point: report here for the headcount'],[0,0,13,'RED','Well exclusion zone: authorised crew only, H2S monitor, full PPE'],[0,0,30,'AMBER','Authorised access: hard hat, safety shoes, coverall, glasses']];
function zoneOf(){for(const z of ZN)if(Math.hypot(S.x-z[0],S.z-z[1])<z[2])return z;return null}
const boxes=[];let boxesBuilt=false;
function buildBoxes(){if(boxesBuilt)return;boxesBuilt=true;DATA.forEach(d=>{(reg[d[0]]||[]).forEach(g=>{const b=new THREE.Box3().setFromObject(g);if(!b.isEmpty())boxes.push({id:d[0],name:d[1].split(' (')[0],b,v:Math.cbrt(Math.max(1e-3,(b.max.x-b.min.x)*(b.max.y-b.min.y)*(b.max.z-b.min.z)))})})})}
