const pr=promptF();if(pr){hDoor.style.display='block';hDoor.textContent=pr}else hDoor.style.display='none';
if(S.zip)t='ESCAPE LINE · Riding the derrickman escape device down the line. Look around; you stop gently at the landing.';else if(S.climb)t='CAUGHT ON THE LADDER · W / S to climb up or down, Shift to climb faster. Three points of contact, fall arrest clipped on.';
