const ROOMS=[{id:'vfd',name:'VFD room',hx:4.5,hz:1.7,inZ:.7,info:'INSIDE THE VFD ROOM · Electricians only. Arc-flash PPE, no live work, keep the exit clear. Press F at the door to leave.'},
{id:'powerhouse',name:'power house',hx:7.8,hz:4.2,inZ:3.2,info:'INSIDE THE POWER HOUSE · Noise above 85 dB: ear defence. Hot exhaust and rotating parts: keep clear of the engines. Press F at the door to leave.'}],_rv=new THREE.Vector3();
