$h('h2hb').style.width=Math.max(0,health)+'%';$h('h2hb').style.background=health<35?'#dc2626':health<65?'#f59e0b':'#22c55e';$h('h2ht').textContent=Math.round(Math.max(0,health))+' %   t = '+Math.round(T)+' s';
$h('h2st').textContent=status(ppm);
const a=$h('h2al');a.className='al'+(alarm?' a'+alarm:'');const names=DET.filter(q=>q.c>=10).map(q=>q.n);if(ppm>=10)names.push('your personal monitor');a.textContent=(alarm==2?'H2S HIGH ALARM: ':'H2S LOW ALARM: ')+(names.join(', ')||'detectors');
